<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class RepairMaintenanceRecord extends Model{protected $fillable=['job_order_no','vehicle_id','driver_id','job_date','job_type','priority','work_status','completed_date','service_provider','contact_person','provider_phone','invoice_no','subtotal','sales_tax','discount','total_paid','payment_method','description','parts','next_service_date','next_service_odometer','notes','is_deleted'];protected $casts=['job_date'=>'date','completed_date'=>'date','next_service_date'=>'date','parts'=>'array','subtotal'=>'decimal:2','sales_tax'=>'decimal:2','discount'=>'decimal:2','total_paid'=>'decimal:2','is_deleted'=>'boolean'];public function vehicle(){return $this->belongsTo(Vehicle::class);}public function driver(){return $this->belongsTo(Driver::class);}}
